-- Apply the same eligibility contract to preference recommendations.
create or replace function public.get_preference_recommendations(page_size integer default 12,page_offset integer default 0)
returns table(user_id uuid,nickname text,avatar_url text,school text,major text,birth_year smallint,personality text,bio text,interests text[],lifestyle text[],relationship_values text[],verified boolean,overall_score integer,interest_score integer,value_score integer,lifestyle_score integer,reasons text[])
language sql stable security definer set search_path='' as $$
with me as(select p.*,pr.* from public.profiles p join public.preferences pr on pr.user_id=p.id where p.id=auth.uid() and public.can_interact(p.id)),s as(select p.*,coalesce((select count(*)from unnest(p.interests)x where x=any(coalesce(nullif(me.preferred_interests,'{}'),me.interests))),0)::int ih,coalesce((select count(*)from unnest(p.relationship_values)x where x=any(coalesce(nullif(me.preferred_values,'{}'),me.desired_traits))),0)::int vh,coalesce((select count(*)from unnest(p.lifestyle)x where x=any(coalesce(nullif(me.preferred_lifestyle,'{}'),me.lifestyle))),0)::int lh,me.city me_city,me.minimum_match_score,me.recommendation_sort from public.profiles p cross join me where public.can_interact(p.id) and p.id<>me.id and p.profile_visible and p.onboarding_complete and(cardinality(me.preferred_life_stages)=0 or p.life_stage=any(me.preferred_life_stages))and(not me.same_city_only or p.city=me.city)and(not me.same_school_only or p.school=me.school)and(not me.verified_only or p.verified)and(cardinality(me.preferred_genders)=0 or p.gender=any(me.preferred_genders))and extract(year from age(current_date,p.birth_date)) between me.age_min and me.age_max and not exists(select 1 from public.user_blocks b where(b.blocker_id=me.id and b.blocked_id=p.id)or(b.blocker_id=p.id and b.blocked_id=me.id))),r as(select s.*,least(99,55+least(20,ih*7)+least(15,vh*6)+least(10,lh*5))::int score from s) select r.id,r.nickname,r.avatar_url,r.school,r.major,extract(year from r.birth_date)::smallint,r.personality,r.bio,r.interests,r.lifestyle,r.relationship_values,r.verified,r.score,least(100,45+r.ih*18)::int,least(100,50+r.vh*20)::int,least(100,50+r.lh*18)::int,array_remove(array[case when r.vh>0 then'符合你看重的关系品质'end,case when r.ih>0 then'命中你的偏好兴趣'end,case when r.city=r.me_city then'生活在同一座城市'end,case when r.verified then'身份已完成认证'end],null) from r where r.score>=r.minimum_match_score order by r.score desc,r.created_at desc limit greatest(1,least(page_size,24)) offset greatest(0,page_offset); $$;
grant execute on function public.get_preference_recommendations(integer,integer) to authenticated;
